def clean(df):
    df = df.copy()
    df['island'] = df['island'].str.strip().str.capitalize()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', ''))
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    return df.groupby('species')['flipper_length_mm'].mean().to_dict()
